# -*- coding: utf-8 -*-
"""Build the integrated shell from the observed Suno layout; preserve the real engine DOM."""
from pathlib import Path
from html.parser import HTMLParser
import re,json,hashlib,shutil

ROOT=Path(__file__).resolve().parent

class Nodes(HTMLParser):
    def __init__(self,text):
        super().__init__(convert_charrefs=False);self.text=text;self.stack=[];self.nodes=[]
        self.offsets=[0]
        for m in re.finditer('\n',text):self.offsets.append(m.end())
        self.feed(text)
    def pos(self):
        line,col=self.getpos();return self.offsets[line-1]+col
    def handle_starttag(self,tag,attrs):
        node={'tag':tag,'attrs':dict(attrs),'start':self.pos()}
        if tag in ('img','input','meta','link','br','hr','source','area','wbr'):return
        self.stack.append(node)
    def handle_endtag(self,tag):
        for i in range(len(self.stack)-1,-1,-1):
            if self.stack[i]['tag']==tag:
                n=self.stack[i];n['end']=self.pos()+len('</'+tag+'>');self.nodes.append(n);self.stack=self.stack[:i];return
    def get(self,tag=None,cls=None,id=None):
        n=next(n for n in self.nodes if (not tag or n['tag']==tag) and (not cls or cls in n['attrs'].get('class','').split()) and (not id or n['attrs'].get('id')==id))
        return self.text[n['start']:n['end']]

def build():
    legacy=Nodes((ROOT/'index.html').read_text())
    # Keep the user's selected mark independent of changes to the app shell.
    selected_logo=ROOT.parent.parent/'output/branding/osmanthus-brand-20261028/osmanthus-logo-08-dark.png'
    logo_asset=ROOT/'assets/brand/osmanthus-logo.png'
    logo_asset.parent.mkdir(parents=True,exist_ok=True)
    shutil.copyfile(selected_logo,logo_asset)
    # Shell rebuilt from the measured Suno workflow; the music engine DOM remains intact.
    (ROOT/'studio-design.css').write_text(""":root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Helvetica Neue","PingFang SC","Microsoft YaHei",sans-serif;color-scheme:dark}#os-mix-28{font-family:inherit}#os-mix-28 *,#os-mix-28 *::before,#os-mix-28 *::after{box-sizing:border-box}#os-mix-28 [hidden]{display:none!important}
""")
    header='''<aside class="studio-sidebar" aria-label="主导航"><div class="studio-sidebar-top"><button type="button" class="rs-brand" data-studio-nav="home" data-rs="home" aria-label="Osmanthus 首页"><img class="studio-brandmark" src="/assets/brand/osmanthus-logo.png" alt="桂花与高音谱号标志" width="28" height="42"><span class="studio-wordmark">Osmanthus</span></button><button type="button" class="studio-sidebar-collapse" data-studio-sidebar-collapse aria-label="收起侧边栏" title="收起侧边栏"><i data-lucide="panel-left-close"></i></button></div><nav class="rs-nav studio-sidebar-nav" aria-label="工作台导航"><button type="button" data-studio-nav="home" data-rs="home" aria-pressed="true"><i data-lucide="house"></i><span>首页</span></button><button type="button" data-studio-nav="create" aria-pressed="false"><i data-lucide="music-2"></i><span>创作</span></button><button type="button" data-studio-nav="editor" aria-pressed="false"><i data-lucide="sliders-horizontal"></i><span>Studio</span></button><button type="button" data-studio-nav="library" data-rs="library" aria-pressed="false"><i data-lucide="library"></i><span>作品库</span></button></nav><div class="studio-sidebar-footer"><div class="studio-local-profile"><span class="studio-profile-avatar" aria-hidden="true">O</span><span>我的音乐空间</span></div></div></aside>'''
    hero='''<section class="rs-hero"><div class="studio-home-topbar"><button type="button" class="studio-home-search" data-studio-nav="library"><i data-lucide="search"></i><span>搜索作品</span></button></div><div class="studio-home-ambient" aria-hidden="true"></div><div class="sd-hero-copy"><h1>把想法写成一首歌</h1></div><div class="rs-promptbox"><textarea id="rs-suno-idea" aria-label="歌曲想法" rows="2" maxlength="2000" placeholder="描述你想创作的歌曲"></textarea><div class="rs-promptbottom"><div class="rs-inputtools"><button type="button" class="os-icon-button" data-studio-nav="create" aria-label="打开创作设置" title="打开创作设置"><i data-lucide="plus"></i></button></div><div class="rs-prompt-actions"><button type="button" class="os-icon-button" data-rs="idea" data-value="中文流行" aria-label="来一点灵感" title="来一点灵感"><i data-lucide="dices"></i></button><button type="button" class="rs-primary" data-rs="create"><i data-lucide="music-2"></i>创作歌曲</button></div></div></div><div class="rs-home-options" data-rs-options hidden><label>风格与配器<input id="studio-style" value="按创作想法" maxlength="60"></label><label>人声音色<input id="studio-voice" value="温暖自然的男声，中文吐字清楚，不要明显电音" maxlength="240"></label></div><p class="rs-note" data-rs-home-note role="status"></p></section><section class="studio-home-highlights" aria-label="开始创作"><article class="studio-feature-card studio-feature-create"><div class="studio-feature-art" aria-hidden="true"><i data-lucide="audio-lines"></i></div><div class="studio-feature-copy"><span class="studio-feature-tag">让灵感成真</span><h2>从一句想法，听见一首歌</h2><p>描述主题、风格和声音，开始你的下一首作品。</p><button type="button" data-studio-nav="create">开始创作<i data-lucide="arrow-up-right"></i></button></div></article><article class="studio-feature-card studio-feature-library"><div class="studio-feature-art" aria-hidden="true"><i data-lucide="disc-3"></i></div><div class="studio-feature-copy"><span class="studio-feature-tag">你的音乐空间</span><h2>每一种想法，都值得留下</h2><p>试听、编配和分享，在作品库继续你的音乐。</p><button type="button" data-studio-nav="library">打开作品库<i data-lucide="arrow-up-right"></i></button></div></article></section>'''
    library='''<section class="rs-library tl-library" aria-label="我的作品列表"><div class="tl-header"><div class="tl-heading"><h2 data-rs-library-heading>最近作品</h2></div></div><div class="tl-toolbar"><label class="tl-search"><i data-lucide="search" aria-hidden="true"></i><input type="search" data-tl-search aria-label="搜索我的作品" placeholder="搜索歌曲"></label><span class="tl-count" role="status"></span></div><div class="tl-columns" hidden></div><div class="rs-projects tl-rows" aria-label="作品"></div><div class="tl-empty" hidden><i data-lucide="music-2"></i><p>你的音乐会出现在这里</p><span>从一个想法开始，创作第一首歌。</span></div></section>'''
    creator='''<main class="studio-shell-main" data-studio-create hidden><section class="studio-composer"><div class="studio-composer-tabs"><span class="studio-composer-tab">歌曲</span></div><div class="studio-composer-mode"><div class="studio-mode-switch" role="tablist" aria-label="创作模式"><button type="button" role="tab" data-create-mode="simple" aria-selected="true">简单</button><button type="button" role="tab" data-create-mode="advanced" aria-selected="false">高级</button></div><span class="studio-model-chip"><i data-lucide="sparkles"></i>标准模型</span></div><div class="studio-composer-scroll" data-create-form><section class="studio-simple-fields" data-create-simple><label class="sr-only" for="studio-simple-prompt">描述歌曲</label><textarea id="studio-simple-prompt" maxlength="2000" placeholder="描述你想创作的歌曲：主题、情绪、风格和声音…"></textarea><div class="studio-simple-tips"><span>让想法自由一点</span><i data-lucide="sparkles" aria-hidden="true"></i></div></section><section class="studio-advanced-fields" data-create-advanced hidden><details class="studio-form-card studio-lyrics-card" open><summary><span><i data-lucide="chevron-down" aria-hidden="true"></i>歌词</span><button type="button" id="studio-lyrics-expand" class="os-icon-button" aria-label="展开歌词编辑" title="展开歌词编辑"><i data-lucide="expand"></i></button></summary><label class="sr-only" for="studio-custom-lyrics">歌词</label><textarea id="studio-custom-lyrics" aria-label="歌词编辑器" rows="12" maxlength="5000" placeholder="写入歌词，或让 AI 帮你写一版"></textarea><div class="studio-lyric-helper"><input id="studio-lyric-instruction" aria-label="歌词创作要求" placeholder="告诉我歌词的主题和想法…" maxlength="2000"><button type="button" id="studio-write-lyrics"><i data-lucide="sparkles"></i>帮我写歌词</button></div></details><details class="studio-form-card" open><summary><span><i data-lucide="chevron-down" aria-hidden="true"></i>风格</span></summary><label class="sr-only" for="studio-custom-style">风格与配器</label><textarea id="studio-custom-style" rows="3" maxlength="1000" placeholder="例如：中文流行、温暖电钢琴、轻盈鼓组、松弛律动"></textarea></details><details class="studio-form-card"><summary><span><i data-lucide="chevron-down" aria-hidden="true"></i>更多选项</span></summary><label class="studio-create-label" for="studio-custom-voice">人声音色</label><textarea id="studio-custom-voice" maxlength="240" rows="2" placeholder="例如：温暖自然的男声，吐字清楚，副歌舒展">温暖自然的男声，中文吐字清楚，不要明显电音</textarea><label class="studio-create-label" for="studio-custom-title">歌曲名称（选填）</label><input id="studio-custom-title" maxlength="120" placeholder="歌曲名称（选填）"></details></section></div><p id="studio-create-status" class="studio-status" role="status" aria-live="polite"></p><div class="studio-create-submit"><button type="button" id="studio-clear-create" class="os-icon-button" aria-label="清空创作表单" title="清空创作表单"><i data-lucide="trash-2"></i></button><button type="button" id="studio-generate-song" class="rs-primary"><i data-lucide="music-2"></i>创作歌曲</button></div></section><section class="studio-results" aria-label="创作结果"><header class="studio-results-header"><div><span>作品空间</span><i data-lucide="chevron-right" aria-hidden="true"></i><strong>我的作品</strong></div></header><div class="studio-results-toolbar"><label class="studio-result-search"><i data-lucide="search" aria-hidden="true"></i><input id="studio-batch-search" type="search" placeholder="搜索歌曲" aria-label="搜索创作结果"></label><select id="studio-batch-sort" aria-label="结果排序"><option value="new">最新</option><option value="old">最早</option></select></div><div class="studio-results-scroll"><div class="studio-create-empty" data-create-results-empty><i data-lucide="music-2" aria-hidden="true"></i><h2>从这里，听见你的想法</h2><p>创作完成后，歌曲会出现在这里。</p></div><section id="studio-batches" aria-label="歌曲生成方案"></section></div></section></main>'''
    sidebar=legacy.get('aside','editor')
    arrangement=legacy.get('div','arrangement-panel');exports=legacy.get('div','export-panel')
    sidebar=sidebar.replace(arrangement,'').replace(exports,'')
    conversation=legacy.get('section','conversation')
    conversation=re.sub(r'<section[^>]*>\s*<div>.*?</div>','<section class="conversation rs-editbox">',conversation,count=1,flags=re.S)
    conversation=re.sub(r'(<textarea[^>]*>).*?(</textarea>)',r'\1\2',conversation,flags=re.S).replace('发送并修改','发送修改')
    conversation=conversation.replace('</form>','<button id="studio-record" type="button" aria-label="语音输入"><i data-lucide="mic"></i></button></form>')
    timeline=legacy.get('section','timeline')
    tools=legacy.get('div','instrument-actions')+'<p id="instrument-status" class="note"></p>'
    timeline=timeline.replace(legacy.get('div','section-heading'),'').replace(legacy.get('p',id='instrument-status'),'')
    timeline=re.sub(r'<p class="timeline-help">.*?</p>','',timeline,flags=re.S)
    timeline=timeline.replace('<div id="tracks">','<div id="studio-mix-lane"><span>整曲</span><div class="wave-wrap"><canvas id="studio-mix-canvas"></canvas><div class="selection"></div><div class="playhead" aria-label="整曲播放游标" role="slider" tabindex="0"></div></div></div><div id="tracks">')
    transport=legacy.get('section','transport').replace('</section>','<label class="studio-volume">音量<input id="studio-volume" aria-label="总播放音量" type="range" min="0" max="1" value="1" step=".01"></label></section>')
    lyrics=legacy.get('section','lyric-panel');score=legacy.get('section','vocal-score-panel')
    voices=legacy.get('section',id='voice-library-panel');unused=legacy.get('section',id='experimental-vocals')
    audit=legacy.get('details','audit').replace('<details','<details open',1)+'<div id="studio-history-restore"></div>'
    shell=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Osmanthus · 音乐工作台</title>
<link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/interactions.css"><link rel="stylesheet" href="/studio-design.css"><link rel="stylesheet" href="/studio.css">
<script src="/studio-icons.js" defer></script></head><body><div id="os-mix-28" class="is-home" data-integrated="true">{header}
<main class="studio-shell-main" data-studio-home>{hero}{library}</main>{creator}
<main class="rs-editor studio-shell-main" data-studio-editor hidden><div class="rs-projecthead"><button type="button" class="studio-editor-brand" data-studio-nav="home" data-rs="home" aria-label="Osmanthus 首页"><img class="studio-brandmark" src="/assets/brand/osmanthus-logo.png" alt="桂花与高音谱号标志" width="24" height="36"><span class="studio-wordmark">Osmanthus</span></button><div><p class="rs-caption">Studio</p><h1 id="song-title">正在读取…</h1><div class="studio-engine-meta" hidden aria-hidden="true"><span id="duration"></span><span id="track-count"></span><span id="ready"></span></div></div><div class="rs-row"><button class="os-icon-button" data-studio-panel="history" aria-label="版本记录" title="版本记录" data-tooltip="版本记录"><i data-lucide="history"></i></button><button class="os-icon-button" data-studio-panel="score" aria-label="歌词与乐谱" title="歌词与乐谱" data-tooltip="歌词与乐谱"><i data-lucide="file-music"></i></button><button class="os-icon-button" data-studio-panel="tools" aria-label="配器与音色" title="配器与音色" data-tooltip="配器与音色"><i data-lucide="layers-2"></i></button><button class="os-icon-button" data-studio-panel="export" aria-label="导出" title="导出" data-tooltip="导出"><i data-lucide="download"></i></button><button class="os-icon-button" data-studio-share-current aria-label="分享作品" title="分享作品"><i data-lucide="share-2"></i></button><button data-studio-video>创作 MV</button></div></div>
<div class="rs-work se-work ux-work sidebar-closed"><aside class="ux-sidebar se-inspector sc-editor-drawer"><div class="sc-drawer-heading"><h3>手动调整</h3><button type="button" data-studio-sidebar aria-label="关闭调整面板"><i data-lucide="x"></i></button></div><details class="studio-manual" open><summary>选区与轨道</summary>{sidebar}</details><div id="studio-sidebar-history"></div></aside><section class="studio-timeline"><div class="sc-timeline-top"><button type="button" data-studio-sidebar aria-label="手动调整" title="手动调整"><i data-lucide="sliders-horizontal"></i></button><div class="studio-transport-slot">{transport}</div></div><div id="studio-sections" aria-label="歌曲段落"></div>{timeline}<div id="studio-candidate-mount"></div></section><section class="studio-ask-shell" aria-label="AI 修改音乐"><div id="studio-target" class="ux-target"></div>{conversation}</section></div>
<div id="notice" role="status" aria-live="polite" hidden></div>
</main>
<dialog id="studio-dialog"><div class="studio-dialog-header"><h2 id="studio-dialog-title"></h2><button id="studio-dialog-close" aria-label="关闭面板"><i data-lucide="x"></i></button></div><p id="studio-dialog-status" role="status" aria-live="polite" hidden></p>
<section data-studio-content="score" hidden>{lyrics}{score}</section>
<section data-studio-content="tools" hidden><h3>原曲器乐分离</h3>{tools}{arrangement}{voices}</section>
<section data-studio-content="history" hidden>{audit}</section>
<section data-studio-content="export" hidden>{exports}<div id="studio-extra-export"><label>导出内容<select id="studio-export-scope"><option value="range">选中片段</option><option value="stems">独立声部（按当前混音）</option></select></label><label>格式<select id="studio-export-format"><option value="wav">WAV</option><option value="mp3">MP3</option></select></label><button id="studio-export-extra">导出所选内容</button><p id="studio-export-status" role="status"></p></div></section>
<section data-studio-content="navigation" hidden><div id="studio-navigation-mount"></div></section>
<section data-studio-content="share" hidden><div id="studio-share-content"></div></section>
<section data-studio-content="song-menu" hidden><div id="studio-song-menu"></div></section>
</dialog><div hidden><div data-create-resume-wrap hidden><button type="button" data-create-resume><span data-create-resume-label></span></button></div><div data-create-draft-empty></div><div data-create-home></div><section id="studio-drafts" aria-label="历史歌词草稿"></section>{unused}<audio id="generation-audio" preload="none"></audio></div>
<div id="studio-global-status" role="status" aria-live="polite" hidden></div></div>
<script>window.osmanthusIntegrated=true;</script><script type="module" src="/studio.js"></script></body></html>'''
    (ROOT/'studio.html').write_text(shell)
    (ROOT/'studio-source.json').write_text(json.dumps({'engine_source':str(ROOT/'index.html'),'engine_sha256':hashlib.sha256((ROOT/'index.html').read_bytes()).hexdigest(),'design_reference':'Measured Suno workflow, 2026-10-28; original Osmanthus implementation and real engine integration.','reference_manifest':str(ROOT.parent.parent/'research/suno-rea-replay-20261028/source-manifest.json'),'scripts':'Only real backend integration; no borrowed application scripts.'},ensure_ascii=False,indent=2))
    print('Built Suno-style Osmanthus shell with preserved engine controls')

if __name__=='__main__':build()
